content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>Doc-audit | FirstRun</title>
7	<meta name="description" content="Which docs pages are stale, which shipped features have no docs, and what your docs team should ship next. Built from the git history.">
8	<meta name="color-scheme" content="light">
9	<link rel="icon" href="../assets/logo.svg" type="image/svg+xml">
10	<link rel="stylesheet" href="../assets/site-nav.css">
11	<link rel="alternate" type="text/markdown" href="/agent.md" title="FirstRun agent quickstart">
12	<link rel="alternate" type="text/plain" href="/llms.txt" title="llms.txt">
13	<link rel="preconnect" href="https://fonts.googleapis.com">
14	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
15	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500&display=swap">
16	<style>
17	:root{
18	--bg:oklch(98.2% .004 255);--panel:oklch(99.7% .0015 255);--sunk:oklch(97.1% .005 255);--hover:oklch(96.2% .007 255);
19	--line:oklch(91.6% .007 255);--line2:oklch(94.6% .005 255);
20	--ink:oklch(22% .012 255);--ink2:oklch(36% .012 255);--mut:oklch(50% .013 255);--faint:oklch(68% .01 255);
21	--acc:oklch(55% .19 256);--acc-bg:oklch(95.6% .026 256);
22	--vio:oklch(52% .2 295);--vio-bg:oklch(95.8% .03 295);
23	--ok:oklch(52% .14 150);--ok-bg:oklch(96.4% .032 150);
24	--bad:oklch(53% .19 27);--bad-bg:oklch(96.6% .02 27);
25	--warn:oklch(52% .12 66);--warn-bg:oklch(96.2% .045 85);
26	--sh:0 1px 2px oklch(30% .02 255/.06);--sh2:0 1px 3px oklch(30% .02 255/.08),0 16px 40px -12px oklch(30% .04 255/.26);
27	--ease:cubic-bezier(.22,1,.36,1);--mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
28	--lift:0 1px 2px oklch(30% .03 256/.05),0 8px 24px -10px oklch(35% .06 256/.16),0 24px 56px -28px oklch(35% .06 256/.18);
29	/* person color slots by rank: --pN ribbon and ring, --dN initials disc, --tN tint */
30	--p0:oklch(62% .15 295);--p1:oklch(62% .15 256);--p2:oklch(62% .15 195);--p3:oklch(62% .15 150);--p4:oklch(62% .15 78);--p5:oklch(62% .15 35);
31	--p6:oklch(62% .15 340);--p7:oklch(62% .15 220);--p8:oklch(62% .15 120);--p9:oklch(62% .15 10);--p10:oklch(62% .15 270);--p11:oklch(62% .15 170);
32	--po:oklch(70% .01 255)}
33	html,body{overflow-x:clip}
34	*{box-sizing:border-box;margin:0}
35	html{background:var(--bg);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%}
36	body{line-height:1.45;font-size:15px;-webkit-font-smoothing:antialiased;background:var(--bg);min-height:100vh}
37	a{color:var(--acc);text-underline-offset:3px}
38	button{font:inherit;color:inherit}
39	code,.mono{font-family:var(--mono)}
40	:focus-visible{outline:3px solid var(--acc);outline-offset:2px;border-radius:8px}
41	[hidden]{display:none!important}
42	.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
43	svg.i{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
44	main{max-width:1240px;margin:0 auto;padding:24px 20px 72px}
45	h1{font-size:34px;line-height:1.1;letter-spacing:-.035em;font-weight:700}
46	h2{font-size:19px;letter-spacing:-.02em;font-weight:650}
47	.lede{font-size:16px;color:var(--mut);margin-top:6px;max-width:58ch}
48	.sec{margin-top:36px}
49	.sec-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}
50	.sec-h p{color:var(--mut);font-size:13.5px}
51	.btn{display:inline-flex;align-items:center;gap:7px;height:36px;padding:0 14px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font-weight:600;font-size:13.5px;text-decoration:none;cursor:pointer;white-space:nowrap;box-shadow:var(--sh)}
52	.btn:hover{background:var(--hover)}
53	.btn.pri{background:var(--vio);border-color:transparent;color:oklch(99% .005 295)}
54	.btn.pri:hover{background:oklch(47% .2 295)}
55	.tile{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:8px;flex:none;color:oklch(99% .005 255)}
56	.tile svg.i{width:16px;height:16px}
57	.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--sh)}
58	.back{display:inline-flex;align-items:center;gap:6px;font-size:13.5px;color:var(--mut);text-decoration:none}
59	.back:hover{color:var(--ink)}
60	.av{width:40px;height:40px;border-radius:10px;background:var(--sunk);border:1px solid var(--line);flex:none;object-fit:cover}
61	
62	/* start view */
63	.lh-top{display:flex;gap:16px;align-items:flex-start}
64	.lh-top .sn-tile{width:52px;height:52px;border-radius:14px;margin-top:4px}.lh-top .sn-tile svg{width:28px;height:28px}
65	.ask{display:flex;gap:8px;align-items:center;margin-top:22px;max-width:640px;padding:6px 6px 6px 16px}
66	.ask svg.i{color:var(--mut)}
67	.ask input{flex:1;min-width:0;font:inherit;font-size:15.5px;border:0;background:none;color:var(--ink);padding:8px 0;outline:0}
68	.mode{display:inline-flex;gap:4px;margin-top:22px;padding:4px;border-radius:12px;background:var(--sunk);border:1px solid var(--line)}
69	.mode button{display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 14px;border:0;border-radius:9px;background:none;font-weight:600;font-size:13.5px;color:var(--mut);cursor:pointer}
70	.mode button svg.i{width:15px;height:15px}
71	.mode button[aria-pressed=true]{background:var(--panel);color:var(--ink);box-shadow:var(--sh)}
72	.ask.top{margin-top:10px}
73	.hint{font-size:13px;color:var(--mut);margin-top:8px;max-width:640px}
74	.steps{list-style:none;padding:0;margin-top:12px;max-width:760px;display:grid;gap:8px}
75	.steps li{display:grid;grid-template-columns:28px minmax(0,1fr);gap:4px 12px;padding:12px 14px}
76	.steps .n{grid-row:1/span 3;width:26px;height:26px;border-radius:99px;display:grid;place-items:center;font-size:13px;font-weight:700;background:var(--vio-bg);color:var(--vio)}
77	.steps b{font-size:14.5px}
78	.steps span{font-size:13px;color:var(--mut)}
79	.steps .opt{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--vio);margin-left:8px}
80	.steps .dw-acts{margin-top:6px}
81	.code{display:flex;align-items:center;gap:8px;margin-top:4px;background:var(--sunk);border:1px solid var(--line);border-radius:9px;padding:6px 6px 6px 12px;font:12.5px var(--mono);overflow-x:auto}
82	.code code{flex:1;white-space:pre}
83	.code .btn{height:30px;padding:0 10px;flex:none}
84	.cmd{display:flex;gap:10px;align-items:flex-start;justify-content:space-between;margin-top:10px;max-width:640px;padding:12px 12px 12px 16px;font-size:13px}
85	.cmd code{white-space:pre;overflow-x:auto}
86	.flow{padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:14px;overflow:hidden}
87	.flow li{list-style:none;display:flex;gap:12px;align-items:flex-start;padding:16px 18px;position:relative}
88	.flow li+li{border-left:1px solid var(--line2)}
89	.flow b{display:block;font-size:14.5px}
90	.flow span{font-size:13px;color:var(--mut)}
91	.flow .tile{background:var(--vio-bg);color:var(--vio)}
92	.alist{list-style:none;padding:0;overflow:hidden}
93	.alist li+li{border-top:1px solid var(--line2)}
94	.alist a{display:grid;grid-template-columns:40px minmax(0,1fr) 220px auto;gap:4px 16px;align-items:center;padding:14px 18px;color:inherit;text-decoration:none}
95	.alist li:hover{background:var(--hover)}
96	.alist .rcpw{padding:0 18px 14px 74px;margin-top:-4px}
97	.alist a.rcp,.rcp{display:inline-flex;grid-template-columns:none;align-items:center;gap:7px;min-height:30px;padding:3px 13px 3px 10px;border-radius:99px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font-size:13px;font-weight:600;text-decoration:none;box-shadow:var(--sh);transition:border-color .15s,color .15s,background .15s}
98	.rcp svg.i{width:15px;height:15px;color:var(--vio)}
99	.rcp .lbl{text-decoration:underline;text-decoration-color:oklch(80% .08 295);text-underline-offset:3px}
100	.rcp .sep{color:var(--faint);font-weight:400}
101	.rcp .amt{font-family:var(--mono);font-variant-numeric:tabular-nums}
102	.rcp .nc{font-weight:400;color:var(--mut)}
103	.rcp .est{font-weight:500;color:var(--mut);font-size:.92em}
104	.alist a.rcp:hover,.rcp:hover{border-color:var(--vio);color:var(--vio);background:var(--vio-bg)}
105	.rcp:hover .lbl{text-decoration-color:currentColor}
106	.rh .acts .rcp{height:36px;min-height:36px;border-radius:10px;padding:0 14px 0 12px}
107	.alist .nm{font-weight:650;font-size:15.5px;letter-spacing:-.01em}
108	.alist .nm small{display:block;font-weight:400;font-size:12.5px;color:var(--mut)}
109	.alist .go{color:var(--vio);font-weight:600;font-size:13.5px;display:inline-flex;gap:4px;align-items:center}
110	.minis{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
111	
112	/* chips */
113	.chip{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 9px;border-radius:99px;font-size:12.5px;font-weight:600;background:var(--sunk);color:var(--ink2);border:1px solid transparent;white-space:nowrap}
114	.chip svg.i{width:13px;height:13px}
115	.c-stale{background:var(--bad-bg);color:var(--bad)}.c-unchecked{background:var(--warn-bg);color:var(--warn)}
116	.c-quiet{background:var(--sunk);color:var(--mut)}.c-aging{background:var(--warn-bg);color:var(--warn)}.c-fresh{background:var(--ok-bg);color:var(--ok)}
117	.c-gap{background:var(--vio-bg);color:var(--vio)}
118	button.chip{cursor:pointer}
119	button.chip[aria-pressed=true]{border-color:currentColor}
120	
121	/* report: head and health */
122	.rh{display:flex;gap:14px;align-items:center;margin-top:10px;flex-wrap:wrap}
123	.rh h1{font-size:28px}
124	.rh .meta{color:var(--mut);font-size:13.5px;margin-top:2px}
125	.rh .acts{margin-left:auto;display:flex;gap:8px}
126	.health{margin-top:18px;padding:14px 16px;display:grid;gap:10px}
127	.bar{display:flex;height:10px;border-radius:99px;overflow:hidden;background:var(--line2);gap:2px}
128	.bar i{display:block;height:100%}
129	.b-stale{background:var(--bad)}.b-unchecked{background:oklch(72% .15 75)}.b-quiet{background:var(--faint)}.b-aging{background:oklch(82% .12 85)}.b-fresh{background:var(--ok)}
130	.hrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
131	.hrow .lbl{font-size:13px;color:var(--mut);margin-right:4px}
132	.hrow .sp{flex:1}
133	
134	/* kind tiles */
135	.k-document .tile{background:var(--bad)}.k-refresh .tile{background:oklch(64% .14 70)}.k-feature .tile{background:var(--acc)}.k-content .tile{background:var(--vio)}
136	.k-automate .tile{background:var(--ok)}.k-quickstart .tile{background:var(--ink)}
137	.allgood{display:flex;gap:12px;align-items:center;padding:16px 18px;flex-wrap:wrap}.allgood p{color:var(--ink2);font-size:14.5px}
138	
139	/* centered section heads, no subtitle */
140	.hc{text-align:center;font-size:clamp(24px,3vw,30px);line-height:1.1;font-weight:700;letter-spacing:-.03em;text-wrap:balance;margin:0 auto 22px;max-width:20em}
141	.cap{text-align:center;color:var(--mut);font-size:13.5px;margin-top:14px}
142	
143	/* team band: the homepage Doc-audit band, full bleed */
144	.tband{position:relative;isolation:isolate;margin:44px calc(50% - 50vw) 0;padding:clamp(52px,6.5vw,88px) 0 clamp(40px,5vw,64px);background:oklch(96.5% .022 300);border-block:1px solid oklch(89.5% .045 300);overflow:hidden}
145	.tband:before,.tband:after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none}
146	.tband:before{background:radial-gradient(90% 55% at 50% 0%,oklch(91.5% .06 300/.85),transparent 70%)}
147	.tband:after{background-image:radial-gradient(circle,oklch(52% .2 295/.15) 1px,transparent 1.4px);background-size:24px 24px;-webkit-mask-image:radial-gradient(70% 50% at 50% 22%,#000,transparent 78%);mask-image:radial-gradient(70% 50% at 50% 22%,#000,transparent 78%)}
148	.tb-in{max-width:1240px;margin:0 auto;padding:0 20px}
149	.tm{background:var(--panel);border:1px solid var(--line);border-radius:20px;box-shadow:var(--lift);padding:24px 24px 18px}
150	.tm-top{display:flex;gap:16px 24px;align-items:flex-start;justify-content:space-between}
151	.tm-say{font-size:16.5px;line-height:1.5;color:var(--ink2);max-width:64ch;min-height:3em;letter-spacing:-.005em;text-wrap:pretty}
152	.tm-say b{color:var(--ink);font-weight:650}
153	.tm-say .dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--pc);margin:0 6px 1px 1px;vertical-align:middle}
154	.tm .mode{margin-top:0;flex:none}
155	.tm .mode button{height:32px;padding:0 13px}
156	
157	/* map: people | ribbons | areas, 52px row pitch */
158	.tm-map{display:grid;grid-template-columns:minmax(200px,23%) minmax(160px,1fr) minmax(180px,25%);margin-top:18px}
159	.tm-hd{font-size:11.5px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--mut);padding:0 0 10px 8px;border-bottom:1px solid var(--line2);margin-bottom:10px}
160	.tm-hd.r{padding-left:14px}
161	.tm-hd.c{border-bottom-color:var(--line2)}
162	.tm-ppl,.tm-ars{display:flex;flex-direction:column;min-width:0}
163	.tm-sv{position:relative;min-width:0}
164	.tm-svg{display:block;width:100%;overflow:visible}
165	.tm-p,.tm-a{position:relative;display:grid;align-items:center;height:44px;margin:4px 0;width:100%;border:0;background:none;border-radius:12px;text-align:left;cursor:pointer;transition:background .18s var(--ease),opacity .18s var(--ease)}
166	.tm-p{grid-template-columns:32px minmax(0,1fr) auto;gap:0 11px;padding:0 12px 0 6px}
167	.tm-a{grid-template-columns:minmax(0,1fr) auto;gap:0 10px;padding:0 10px 0 14px}
168	.tm-p:hover,.tm-a:hover{background:var(--hover)}
169	.tm-p[aria-pressed=true],.tm-a[aria-pressed=true]{background:var(--tc,var(--vio-bg));box-shadow:inset 0 0 0 1.5px var(--pc,var(--vio))}
170	.tm-p .nm,.tm-a .nm{display:block;font-size:14.5px;font-weight:600;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.25}
171	.tm-p .sb{display:block;font-size:12px;color:var(--mut);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
172	.tm-a .pth{display:block;font:11.5px/1.3 var(--mono);color:var(--faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;direction:rtl;text-align:left}
173	.tm-a .pth bdi{direction:ltr;unicode-bidi:isolate}
174	.tm-p .pk{font-size:11.5px;font-weight:650;color:var(--vio);background:var(--vio-bg);border-radius:99px;padding:2px 8px;white-space:nowrap;font-variant-numeric:tabular-nums}
175	.tm-o{cursor:default}.tm-o:hover{background:none}
176	.ev{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--sunk);border:1.5px dashed oklch(78% .01 255);font-size:11.5px;font-weight:650;color:var(--mut);font-variant-numeric:tabular-nums}
177	/* focus state: one person or one area lights up, the rest steps back */
178	.tm.f .tm-p:not(.hi),.tm.f .tm-a:not(.hi){opacity:.38}
179	.tm.f .tm-a.hi .nm{font-weight:700;color:var(--ink)}
180	.rb{fill-opacity:.3;mix-blend-mode:multiply;transition:fill-opacity .18s var(--ease)}
181	.tm-svg.f .rb{fill-opacity:.055}
182	.tm-svg.f .rb.hi{fill-opacity:.8}
183	.tm-svg .nd{transition:opacity .18s var(--ease)}
184	.tm-svg.f .nd:not(.hi){opacity:.25}
185	.tm-svg.pre .rb{opacity:0}
186	.tm.f .ar:not(.hi){opacity:.45}
187	.tm-svg.in .rb{animation:rbin .5s var(--ease) both;animation-delay:calc(var(--i)*12ms);transform-box:view-box;transform-origin:0 50%}
188	@keyframes rbin{from{opacity:0;transform:scaleX(.15)}to{opacity:1;transform:none}}
189	
190	/* badges */
191	.bdg{display:inline-flex;align-items:center;gap:4px;height:22px;padding:0 8px;border-radius:99px;font-size:11.5px;font-weight:650;white-space:nowrap;background:var(--sunk);color:var(--mut)}
192	.bdg.warn{background:var(--warn-bg);color:var(--warn)}
193	.bdg.qt{background:none;border:1px dashed oklch(80% .01 255)}
194	.bdg.dc{background:var(--acc-bg);color:var(--acc)}
195	
196	/* avatars: ring in the person's color, initials under the photo */
197	.avr{position:relative;display:inline-grid;place-items:center;flex:none;width:var(--s,32px);height:var(--s,32px);border-radius:50%;background:var(--panel);box-shadow:0 0 0 2px var(--pc,var(--po))}
198	.avr .ini{width:100%;height:100%;border-radius:50%;display:grid;place-items:center;background:var(--dc,oklch(48% .02 255));color:oklch(99% .004 255);font-size:calc(var(--s,32px)*.36);font-weight:650;letter-spacing:.01em;line-height:1}
199	.avr img{position:absolute;inset:2px;width:calc(100% - 4px);height:calc(100% - 4px);border-radius:50%;object-fit:cover;background:var(--panel);transition:opacity .2s var(--ease)}
200	.avr.none{background:none;box-shadow:none;border:1.5px dashed oklch(74% .01 255)}
201	
202	/* By-area list */
203	.tm-list{list-style:none;padding:0;margin-top:18px;display:none}
204	.tm.byarea .tm-map{display:none}.tm.byarea .tm-list{display:block}
205	.tm-list li+li{border-top:1px solid var(--line2)}
